def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    pressure_scores = []

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            opp_pressure = 0.0
            opp_pressure += max(0, 6 - opp.get('hp', 10)) * 4.0
            opp_pressure += opp.get('no_water_days', 0) * 10.0
            opp_pressure += max(0.0, DAILY_SALARY - opp.get('budget', 0.0)) * 0.05
            if bid is not None:
                opp_pressure += float(bid) * 0.15
            pressure_scores.append(opp_pressure)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    sorted_bids = sorted(prev_bids) if prev_bids else []
    highest_prev = sorted_bids[-1] if sorted_bids else 0.0
    second_prev = sorted_bids[-2] if len(sorted_bids) >= 2 else highest_prev
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_pressure = max(pressure_scores) if pressure_scores else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    my_urgency = 0.0
    my_urgency += max(0, 5 - hp) * 9.0
    my_urgency += no_water_days * 14.0
    if day >= 8:
        my_urgency += 6.0

    safe = hp >= 7 and no_water_days == 0
    danger = hp <= 4 or no_water_days >= 2
    critical = hp <= 2 or no_water_days >= 3

    if critical:
        bid = max(92.0, highest_prev + 3.0, second_prev + 5.0)
    elif danger:
        bid = max(72.0 + 18.0 * scarcity, second_prev + 2.5, avg_prev * 0.82)
    elif safe and supply >= 21:
        bid = max(18.0, min(46.0, avg_prev * 0.42 + 4.0))
    elif safe and supply >= 18:
        bid = max(28.0, min(58.0, second_prev * 0.62 + 3.0))
    else:
        bid = max(45.0 + 12.0 * scarcity, second_prev * 0.78 + 2.0)

    if highest_prev >= 130.0 and safe:
        bid = min(bid, 44.0)
    elif highest_prev >= 110.0 and safe and supply >= 18:
        bid = min(bid, 52.0)

    if max_pressure >= 28.0 and not safe:
        bid = max(bid, second_prev + 3.0)

    if day == 1 and supply >= 20 and hp >= 8:
        bid = min(bid, 35.0)

    reserve = 0.0
    if hp >= 6:
        reserve = DAILY_SALARY * 1.2
    elif hp >= 4:
        reserve = DAILY_SALARY * 0.6

    affordable = max(0.0, budget - reserve)
    if critical:
        cap = budget
    else:
        cap = max(20.0, affordable)
        cap = min(cap, budget)

    bid = min(bid, cap)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids to infer how hard others are fighting.
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Estimate how competitive the market was.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Determine urgency.
    hp_critical = my_hp <= 2.5
    hp_low = my_hp <= 5.0
    no_water_urgent = my_no_water_days >= 2

    # Supply pressure: lower supply means each unit of water is scarcer.
    # Map supply in [15,25] to [1.0,0.0] pressure.
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_pressure = 0.5

    # Base bid: slightly below the field's likely overbidding level.
    # If yesterday bids were high, we avoid matching them unless we are in danger.
    base = DAILY_SALARY * (0.40 + 0.25 * supply_pressure)

    # If field bid very high yesterday, reduce unless we are threatened.
    if highest_prev_bid >= DAILY_SALARY * 1.25:  # ~112.5+
        if hp_critical or no_water_urgent:
            base = DAILY_SALARY * (0.75 + 0.15 * supply_pressure)
        elif hp_low:
            base = DAILY_SALARY * (0.55 + 0.15 * supply_pressure)
        else:
            base = DAILY_SALARY * (0.35 + 0.10 * supply_pressure)
    elif avg_prev_bid > DAILY_SALARY * 0.95:  # ~85+
        if hp_critical or no_water_urgent:
            base = DAILY_SALARY * (0.70 + 0.15 * supply_pressure)
        else:
            base = DAILY_SALARY * (0.50 + 0.10 * supply_pressure)

    # If we are behind on water, increase.
    if no_water_urgent:
        base *= 1.15
    if hp_critical:
        base *= 1.25

    # Convert base to a conservative cap: don't spend beyond what keeps us alive.
    # With 10 days total, spending much more than ~1/3 of budget per day is risky.
    cap = my_budget * 0.35

    bid = min(my_budget, cap, base)

    # Ensure bid is at least a small positive amount if we can.
    if bid < 1.0:
        bid = min(my_budget, 1.0)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
