    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0

    current_bid = DAILY_SALARY * 0.6

    if my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] == 3:
        current_bid = DAILY_SALARY * 0.8

    if max_prev_bid > DAILY_SALARY * 0.8:
        current_bid = max(current_bid, max_prev_bid + 10)
    elif max_prev_bid > DAILY_SALARY * 0.5:
        current_bid = max(current_bid, max_prev_bid + 2)

    num_water_slots = int(day_context['supply'] // WATER_REQ)

    if num_water_slots == 1:
        current_bid = max(current_bid, DAILY_SALARY * 0.75)
    elif num_water_slots >= 2:
        current_bid = max(current_bid, DAILY_SALARY * 0.55)

    final_bid = min(my_status['budget'], current_bid)

    return max(1.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    # Learn from yesterday's bids
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # My desperation level
    no_water = my_status['no_water_days']
    hp = my_status['hp']

    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
        # If yesterday was very high, we may need to match or exceed
        if max_yesterday > DAILY_SALARY * 0.7:
            base_bid = max_yesterday + 1.0
        else:
            base_bid = DAILY_SALARY * 0.5
    else:
        base_bid = DAILY_SALARY * 0.5

    # Adjust for water need
    if no_water >= 2 or hp <= 2:
        bid = max(base_bid, DAILY_SALARY * 0.9)
    elif no_water == 1:
        bid = max(base_bid, DAILY_SALARY * 0.7)
    else:
        bid = base_bid

    # Ensure we don't exceed budget
    bid = min(my_status['budget'], bid)
    # Also ensure non-negative
    if bid < 0:
        bid = 0.0
    return bid
